void GUI_App::switch_printer_agent()
{
    if (!m_agent) {
        BOOST_LOG_TRIVIAL(warning) << __FUNCTION__ << ": no agent exists";
        return;
    }

    // Read printer_agent from config, falling back to default
    std::string effective_agent_id = ORCA_PRINTER_AGENT_ID;
    std::string cloud_agent_id = ORCA_CLOUD_PROVIDER;
    if (preset_bundle->is_bbl_vendor()) {
        effective_agent_id = BBL_PRINTER_AGENT_ID;
        cloud_agent_id = BBL_CLOUD_PROVIDER;
        // Fork policy: fake mode substitutes the Bambu agent. Additive; no upstream line deleted.
        if (const std::string fake_id = fake_bambu_printer_agent_id(app_config); !fake_id.empty())
            effective_agent_id = fake_id;
    } else {
        const DynamicPrintConfig& config = preset_bundle->printers.get_edited_preset().config;
        if (config.has("printer_agent")) {
            const std::string& value = config.option<ConfigOptionString>("printer_agent")->value;
            if (!value.empty())
                effective_agent_id = value;
        }
    }

    // Check if agent is registered
    if (!NetworkAgentFactory::is_printer_agent_registered(effective_agent_id)) {
        BOOST_LOG_TRIVIAL(warning) << __FUNCTION__ << ": unregistered agent ID '" << effective_agent_id
                                   << "', keeping current agent";
        // Keep current agent, don't switch
        return;
    }

    std::string current_agent_id;
    if (m_agent->get_printer_agent())
        current_agent_id = m_agent->get_printer_agent()->get_agent_info().id;

    if (current_agent_id != effective_agent_id) {
        std::string log_dir = data_dir();
        std::shared_ptr<ICloudServiceAgent> cloud_agent = m_agent->get_cloud_agent(cloud_agent_id);

        // Create new printer agent via registry
        std::shared_ptr<IPrinterAgent> new_printer_agent =
            NetworkAgentFactory::create_printer_agent_by_id(effective_agent_id, cloud_agent, log_dir);

        if (!new_printer_agent) {
            BOOST_LOG_TRIVIAL(warning) << __FUNCTION__ << ": failed to create agent '" << effective_agent_id << "', keeping current agent";
            return;
        }

        // Swap the agent
        m_agent->set_printer_agent(new_printer_agent);
        sidebar().update_all_preset_comboboxes();

        BOOST_LOG_TRIVIAL(info) << __FUNCTION__ << ": printer agent switched to " << effective_agent_id;

        // Auto-switch MachineObject
        select_machine(effective_agent_id);
    }
}

bool set_printer_access_code(const std::string& dev_id, const std::string& code, wxString& error)
{
    // ConnectPrinterDialog::on_button_confirm's rule and its one call.
    const bool valid = std::all_of(code.begin(), code.end(), [](char c) {
        return ('0' <= c && c <= '9') || ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z');
    });
    if (!valid) {
        error = _L("Invalid input.");
        return false;
    }
    DeviceManager* devices = wxGetApp().getDeviceManager();
    MachineObject* machine = devices ? devices->get_my_machine(dev_id) : nullptr;
    if (!machine) {
        error = _L("This printer is no longer on your network.");
        return false;
    }
    machine->set_user_access_code(code);
    return true;
}

bool select_bed_type(Plater& plater, int bed_type_value)
{
    const std::vector<BedType>& supported = plater.sidebar().get_cur_combox_bed_types();
    const auto found = std::find(supported.begin(), supported.end(), BedType(bed_type_value));
    if (found == supported.end())
        return false;
    // set_bed_type_accord_combox selects *and notifies*, so Orca's own
    // on_select_bed_type runs: it owns the project-config write, the
    // app-config record, the invalidation of every plate still on the default
    // bed, and the re-render. None of that is repeated here.
    //
    // Ownership note: a bed type is machine state to the person and project
    // state to Orca. The chip presents it under the printer because that is
    // where the person looks for it; the value still lives in the project.
    plater.sidebar().set_bed_type_accord_combox(BedType(bed_type_value));
    return true;
}

void open_settings_tab(Preset::Type type)
{
    Tab* tab = wxGetApp().get_tab(type);
    if (tab == nullptr)
        return;
    // PlaterPresetComboBox::switch_to_tab: the Tab activates its own page and
    // ParamsPanel, including clearing the previous page.
    wxGetApp().params_dialog()->Popup();
    tab->OnActivate();
    tab->restore_last_select_item();
}

