        ref={root}
        onKeyDown={(event) => {
          if (event.key === 'Escape') {
            setOpen(false);
            button.current?.focus();
          }
          if (open && ['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) {
            event.preventDefault();
            const items = Array.from(
