// -- Numbers and lists --------------------------------------------------------

// "0.4", "0.25", "1.0": two decimals, trailing zeros dropped down to one, as
// the printer profiles spell nozzle sizes.
export function numberText(value: number): string {
  let text = value.toFixed(2);
  while (text.length > 3 && text.endsWith('0')) text = text.slice(0, -1);
  return text;
}

export function mm(value: number): string {
  return `${numberText(value)} mm`;
}

// "a, b and c"
export function listed(items: string[]): string {
  return items.map((item, index) => (index === 0 ? '' : index + 1 === items.length ? ' and ' : ', ') + item).join('');
}

// "0.2, 0.4, 0.6 and 0.8 mm"
export function sizesText(nozzles: number[]): string {
  return `${listed(nozzles.map(numberText))} mm`;
}

function spoolName(spool: PrinterSpoolInfo): string {
  return spool.name || spool.material;
}

// "PLA Matte and PETG", or "none"
function spoolsText(spools: PrinterSpoolInfo[]): string {
  return spools.length === 0 ? 'none' : listed(spools.map(spoolName));
}

// What a printer has loaded, as one line: "AMS lite · PLA Matte + 3".
export function spoolSummary(ams: string, spools: PrinterSpoolInfo[]): string {
  if (spools.length === 0) return ams;
  const first = spoolName(spools[0]) + (spools.length > 1 ? ` + ${spools.length - 1}` : '');
  return ams ? `${ams} · ${first}` : first;
}

// -- The panel's fixed words --------------------------------------------------

// A likely answer, rather than a standing invitation.
export function placeholder(session: PrinterSessionPayload): string {
  return session.mode === 'add'
    ? 'e.g. "bambu a1 mini" or "not sure, the small one"'
    : 'e.g. "I put a 0.6 nozzle on it" or "loaded black PETG"';
}

export const ADD_LABEL = 'Add this printer';
export const REJECT_LABEL = 'Not this one';

// What stands in for a tool-only turn while it still has no words: which
// tool the mode's own instructions let the model call. Add's only tool
// looks through the printer list; Change's only tool works out and applies
// a change, so it does not name a list that mode never shows.
export function workingText(mode: PrinterSessionPayload['mode']): string {
  return mode === 'add' ? 'Looking through the printer list…' : 'Working on it…';
}

// The panel's own first line, which the model is shown as having said: the
// same promise every time the panel opens.
export function opening(session: PrinterSessionPayload): string {
  if (session.mode === 'change') {
    const name = session.context?.printer?.name || session.facts.printer.name || 'this printer';
    return `This is the ${name}. Tell me what changed on it, or ask anything about it: nozzle, plate, spools. A photo of the part works too.`;
  }
  return (
    'Which printer do you have? Tell me the brand and model, or share a photo of its label. ' +
    "Not sure? Tell me what you know, and I'll help you find it."
  );
}

// -- The cards in the thread --------------------------------------------------

// Under a printer's name: what the printer reported, or its size.
export function cardSubline(card: PrinterCardInfo): string {
  const device = card.device;
  if (!device) return card.buildVolume;
  let text = `${mm(device.nozzle)} nozzle`;
  if (device.spools.length > 0) text += ` · ${spoolSummary(device.ams, device.spools)}`;
  if (device.reported) text += ' · read from the printer just now';
  return text;
}

// The undo row: "Nozzle set to 0.6 mm", "Spools updated", or both.
export function undoText(block: PrinterBlock): string {
  const parts: string[] = [];
  if (block.changed?.nozzle) parts.push(`Nozzle set to ${mm(block.changed.nozzle.after)}`);
  if (block.changed?.spools) parts.push(parts.length > 0 ? 'spools updated' : 'Spools updated');
  return parts.join(', ');
}

// The change card's title.
export function changeTitle(nozzle: boolean, spools: boolean): string {
  return nozzle && spools ? 'Change nozzle and spools' : nozzle ? 'Change nozzle' : 'Change spools';
}

// -- What the model is told after a tap ---------------------------------------
// Statements of what the person did, never instructions. The app posts them
// only when the tap goes through as described.

export function rejectedNote(name: string): string {
  return `The person said ${name} is not their printer.`;
}

export function chosenNote(card: PrinterCardInfo): string {
  return `Selected ${card.name}. Nozzle choice: ${mm(card.assumed.nozzle)}.`;
}

// For a network printer the app matched to a model in the list.
export function networkNote(printer: NetworkPrinterInfo): string {
  const match = printer.match;
  if (!match) return '';
  const start = `Selected ${match.name} (${printer.serial})`;
  return match.reported
    ? `${start}, reporting a ${mm(match.nozzle)} nozzle.`
#pragma once

// The one route from the printer panel to Orca. Every read comes from an
// existing owner -- the packaged catalogue, Bambu's device list, the printer
// preset collection, the spool store -- and every write goes through
// SetupCommands or Printers::, never through a preset or a device directly.

#include "PrinterBackend.hpp"
#include "PrinterCatalog.hpp"
#include <chrono>

namespace Slic3r::GUI { class Plater; }
namespace Slic3r::GUI::JusPrin::Workspace { class SpoolStore; }

namespace Slic3r::GUI::JusPrin::PrinterSetup {

class OrcaPrinterBackend : public IPrinterBackend
{
public:
    // `spools` is the app-level store the rest of the shell already shares;
    // without one this backend reports a printer's spools as unknown and
    // refuses to change them.
    OrcaPrinterBackend(Plater& plater, PrinterCatalog catalog, Workspace::SpoolStore* spools);

    const std::vector<CatalogPrinter>& catalog() const override { return m_models; }
    std::vector<DiscoveredPrinter> network_printers() const override;
    std::vector<SavedPrinter>      saved_printers() const override;

    std::string add_printer(const AddPrinterRequest& request, SavedPrinter& added) override;
    std::string change_printer(const ChangePrinterRequest& request, SavedPrinter& changed) override;

    ManualPrinterResult run_manual_setup() override;
    void open_printer_settings(const std::string& name) override;
    PrinterConnectionInfo connection(const std::string& name) override;
    void prepare_connection(const std::string& name) override;
    void sign_in_to_bambu() override;
    std::string connect_printer(const std::string& name, const std::string& device_id,
                               const std::string& access_code) override;
    std::string connect_host(const std::string& name, const std::string& host_type,
                            const std::string& address, const std::string& api_key) override;

private:
    const CatalogPrinter* model_of(const std::string& printer_name) const;

    Plater&                     m_plater;
    PrinterCatalog              m_catalog;
    Workspace::SpoolStore*      m_spools{nullptr};
    // One entry per model, built once from the catalogue's per-variant
    // candidates: the panel proposes printers, and a nozzle is a fact about
    // the printer rather than a printer of its own.
    std::vector<CatalogPrinter> m_models;
    struct ConnectionAttempt {
        std::string name;
        std::string device_id;
        std::chrono::steady_clock::time_point started;
        std::chrono::system_clock::time_point observation_start;
    };
    std::optional<ConnectionAttempt> m_connection_attempt;
    struct HostAttempt {
        std::string name, host_type, address, api_key;
        std::string state;
        std::string message;
    };
    std::optional<HostAttempt> m_host_attempt;
};

} // namespace Slic3r::GUI::JusPrin::PrinterSetup
# Fake Bambu printer (in-process)

Substitutes `FakeBambuAgent` for Bambu's closed network plugin so header menu,
Select Machine, and print can run without hardware. It is not a network fake:
MQTT, FTPS, and discovery are not implemented.

The Klipper/Moonraker simulator lives on `jusprin-newui-fakeprinter` under
`tests/printer_sim/` and covers print-host printers. Do not add a Bambu network
fake unless asked.

This file is the operator guide for humans and AI agents.

## What success looks like

- Log: `switch_printer_agent: printer agent switched to jusprin-fake-bambu`
- Log: `set_selected_machine=FAKE001` and later `FakeBambuAgent: connected FAKE001`
- Printer chip shows `Bambu Lab A1 mini · 0.4` (nickname and nozzle only)
- Click the **printer** half of that chip. The **first menu row** is Idle,
  Printing, or Offline. Those words are never on the chip itself.

If the log says `moonraker` or `orca`, the fake is not in the path. Stop and
fix the preset; do not patch UI gates.

## Turn it on

Quit JusPrin first. The app rewrites `JusPrin2.conf` on exit.

`JusPrin2.conf` is JSON. Under the scratch datadir:

```json
"jusprin": { "fake_printer": true }
```

JSON `true` is what the app stores; `get("jusprin", "fake_printer")` reads as
the string `"true"`. An INI `[jusprin]` block is ignored.

Keep a **Bambu Lab printer** selected: a real system preset, typically
`Bambu Lab A1 mini 0.4 nozzle`, or a named printer that inherits one.
`is_bbl_vendor()` must be true; it reads the inherited `printer_model`, so
either works. An embedded 3mf preset named
`Bambu Lab A1 mini 0.4 nozzle(Tape_4_3MF.3mf)` is not enough; the agent stays
`orca`.

**Add a printer…** in the printer menu installs the system preset and saves it
as a named printer (a user profile such as `Bambu Lab A1 mini`), which is what
Home lists. Alternatively copy `Resources/profiles/BBL` into
`<datadir>/system/` and add the A1 mini model to the `models` array in
`JusPrin2.conf`, then select the system preset. Opening
`~/Downloads/Tape_4_3MF.3mf` only helps after that vendor is installed.

Launch a **scratch** `--datadir`. Do not point fake mode at the everyday
config. Set `"single_instance": false` in the `app` object if another JusPrin
is already running. Do not pass `--no-single-instance`; Boost rejects it.

The fake emulates printer type `N1` (A1 mini). Select Machine lists it as
**JusPrin Fake A1 mini (LAN)**.

## Drive state

Write `<datadir>/jusprin/fake_printer.json` (create `jusprin/` if needed). The
fake rereads it about once a second.

```json
{"state":"printing","progress":0.4,"nozzle":210,"bed":60,"offline":false}
```

| Field | Meaning |
|---|---|
| `state` | `idle`, `heating`/`prepare`, `printing`/`running`, `pause`, `finished`, `failed` |
| `progress` | 0–1, mapped to `mc_percent` |
| `nozzle`, `bed` | °C |
| `offline` | `true` stops `push_status`; after ~30 s the menu first row is Offline |
| `spools` | loaded AMS spools; see below. Absent leaves whatever was last set |

No `spools` (or an empty array) reports no AMS at all, same as before this

