    </div>
  );
});

// The code a Bambu printer shows under Settings > Network. It goes with Add
// to the app, which connects the printer; it is never part of the chat.
export function PrinterAccessCode({ value, onChange }: { value: string; onChange: (value: string) => void }) {
  return (
    <input
      className="printer-access-code"
      type="text"
      autoComplete="off"
      spellCheck={false}
      maxLength={32}
      aria-label="Access code"
      placeholder="access code, optional"
      value={value}
      onChange={(event) => onChange(event.target.value)}
    />
  );
}

export interface ChipRowProps {
  canAdd: boolean;
  disabled: boolean;
  onAdd: () => void;
  onReject: () => void;
}

// What the person can do with the printer on the card. Both act natively;
// adding leads, because the tap is the approval.
export const PrinterChipRow = memo(function PrinterChipRow({ canAdd, disabled, onAdd, onReject }: ChipRowProps) {
  if (!canAdd) return null;
  return (
    <div className="printer-chips">
      <button type="button" className="printer-chip printer-chip-primary" disabled={disabled} onClick={onAdd}>
        {ADD_LABEL}
      </button>
      <button type="button" className="printer-chip printer-chip-plain" disabled={disabled} onClick={onReject}>
        {REJECT_LABEL}
    open(state({ session: session({ mode: 'change', canAdd: false }) }));
    expect(screen.getByPlaceholderText('e.g. "I put a 0.6 nozzle on it" or "loaded black PETG"')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Add a photo' })).toBeInTheDocument();
  });

  it('adds the printer and refuses it natively, never as the person speaking', async () => {
    const host = open();

    await userEvent.click(screen.getByRole('button', { name: 'Add this printer' }));
    expect(host.lastOfType('printer_action')!.payload).toEqual({ action: 'add', id: '' });

    // The note the model reads is written here, from the printer on the card.
    await userEvent.click(screen.getByRole('button', { name: 'Not this one' }));
    expect(host.lastOfType('printer_action')!.payload).toEqual({
      action: 'reject',
      id: '',
      note: 'The person said Bambu Lab A1 mini is not their printer.',
    });
    expect(host.lastOfType('user_message')).toBeUndefined();
  });

  it('sends an access code with Add, and never into the chat', async () => {
    const host = open(state({ session: session({ accessCode: true }) }));

    await userEvent.type(screen.getByRole('textbox', { name: 'Access code' }), '12345678');
    await userEvent.click(screen.getByRole('button', { name: 'Add this printer' }));
    expect(host.lastOfType('printer_action')!.payload).toEqual({
      action: 'add',
      id: '',
      accessCode: '12345678',
      note: 'An access code was entered.',
    });
    expect(host.received.some((envelope) => envelope.type === 'user_message')).toBe(false);
    expect(JSON.stringify(host.received.filter((envelope) => envelope.type !== 'printer_action'))).not.toContain('12345678');
  });

  it('offers no access code for a printer that was not found on the network', () => {
    open();
    expect(screen.queryByRole('textbox', { name: 'Access code' })).toBeNull();
  });

  it('confirms a change on its own card and hides the tools that only show printers', async () => {
    const activity = (tool: string, extra: Partial<ToolActivityInfo>): ToolActivityInfo => ({
      actionId: `t-${tool}`,
      correlationId: 'm-1',
      server: 'jusprin',
      tool,
      title: tool === 'printer_change' ? 'Change nozzle' : 'Show the printers you mean',
      arguments: {},
      actionClass: tool === 'printer_change' ? 'mutation' : 'read_only',
    void verify_saved_bambu_connection()
    {
        // Exercise the actual adapter and parsed device observations with the
        // in-process fake. This proves state ownership, not network authentication.
        wxGetApp().app_config->set("jusprin", "fake_printer", "true");
        auto backend = std::make_shared<PrinterSetup::OrcaPrinterBackend>(
            *m_plater, PrinterSetup::PrinterCatalog::load(Slic3r::resources_dir()), nullptr);
        PrinterSetup::AddPrinterRequest request;
        request.vendor_id = "BBL";
        request.model_id = "Bambu Lab A1 mini";
        request.variant = "0.4";
        request.name = "Connection fixture";
        PrinterSetup::SavedPrinter saved;
        check(backend->add_printer(request, saved).empty(), "connect_fixture_saved_without_device");
        SetupCommands::select_printer_preset(*m_plater, kSetupFixturePrinter);
        const bool dirty = m_plater->is_project_dirty();
        backend->prepare_connection(saved.name);
        wait_until([backend, name = saved.name] { return !backend->connection(name).candidates.empty(); },
            "connect_fake_discovered_by_real_adapter", [self = shared_from_this(), backend, name = saved.name, dirty] {
                const auto info = backend->connection(name);
                const std::string device = info.candidates.front().id;
                self->check(info.state == "not_configured", "unlinked_online_device_is_not_a_connected_saved_printer");
                self->check(backend->connect_printer(name, device, "").empty(), "connect_existing_saved_bambu");
                self->check(backend->connection(name).state == "connecting", "connect_waits_for_fresh_device_data");
                self->check(backend->connect_printer(name, device, "").empty(), "duplicate_connect_is_idempotent");
                self->wait_until([backend, name] { return backend->connection(name).state == "verified"; },
                    "connect_verified_from_parsed_fake_data", [self, backend, name, device, dirty] {
                        const auto printers = backend->saved_printers();
                        self->check(std::count_if(printers.begin(), printers.end(), [&](const auto& p) {
                            return p.name == name && p.device_id == device;
                        }) == 1, "connect_keeps_one_saved_identity");
                        self->check(self->selected_printer() == kSetupFixturePrinter &&
                            self->m_plater->is_project_dirty() == dirty, "connect_preserves_unrelated_project_selection_and_edits");
                        self->finish();
                    });
            });
    }

    void check(bool condition, const std::string& name)
    {
        std::cerr << "HARNESS CHECK " << name << ' ' << (condition ? "PASS" : "FAIL") << '\n';
        if (!condition)
            ++m_failures;
    }

    // Every label rendered by the status row, joined. Read by walking the
    // widget tree so the row needs no test-only accessor.
    static wxString status_row_labels(wxWindow* window)
    {
        wxString text = window->GetLabel() + "\n";
        for (wxWindow* child : window->GetChildren())
            text += status_row_labels(child);
        return text;
    }

    void verify_stock_mode()
    {
        check(installed_shell() == nullptr, "stock_mode_installs_no_shell");
        check(m_notebook->GetBtnsListCtrl()->IsShown(), "stock_mode_keeps_tab_strip");
        check(m_plater->is_sidebar_available(), "stock_mode_keeps_sidebar_available");

  import type { PrinterInfo } from '../bridge/protocol';
  import { MoreGlyph } from './Glyphs';
  
  export interface PrinterActions {
>   onConnect?: (id: string) => void;
    onOpenSettings: (id: string) => void;
    // A device is renamed in Orca's own dialog, so it is sent without a name.
    onRename: (id: string, name?: string) => void;
    onRemove: (id: string) => void;
            <MoreGlyph />
          </button>
          {open && (
            <div className="printer-menu" role="menu" aria-label={`Actions for ${printer.name}`}>
>             {named && actions.onConnect && <button type="button" role="menuitem" onClick={() => {
                setOpen(false);
>               actions.onConnect?.(printer.id);
>             }}>Connect printer…</button>}
              <button
                type="button"
                role="menuitem"
                disabled={!printer.canOpenSettings}

