const r='src/slic3r/GUI/JusPrin/';
edit('src/slic3r/GUI/GUI_App.hpp',s=>s.replace('#include <memory>','#include <memory>\n#include <utility>'));
edit(r+'Shell/ShellController.hpp',s=>s.replace('#include <memory>','#include <memory>\n#include <utility>'));
edit(r+'Shell/ShellController.cpp',s=>s.replace('        wxGetApp().show_config_wizard_on_startup = m_saved_show_config_wizard_on_startup;\n    wxGetApp().printer_agent_override','        wxGetApp().show_config_wizard_on_startup = m_saved_show_config_wizard_on_startup;\n        wxGetApp().printer_agent_override'));
edit(r+'AgentUI/src/styles.css',s=>s.replace('/* The access code of a printer found on the network: the panel\'s own field,\n   whose value goes to the app with Add and never into the chat. */\n',''));
edit(r+'HomeUI/src/App.test.tsx',s=>s.replaceAll("'Connect printer…'","'Connection settings…'"));
edit('tests/shell/shell_harness.cpp',s=>{
 s=s.replace('                self->check(backend->connect_printer(name, device, "").empty(), "duplicate_connect_is_idempotent");',`                self->check(backend->connect_printer(name, device, "").empty(), "duplicate_connect_is_idempotent");
                wxGetApp().getDeviceManager()->set_selected_machine("");
                const auto interrupted = backend->connection(name);
                self->check(interrupted.state == "failed" && interrupted.message.find("Another printer was selected") != std::string::npos &&
                    interrupted.message.find("access code") == std::string::npos, "selection_interruption_does_not_blame_credentials");
                self->check(backend->connect_printer(name, device, "").empty(), "interrupted_connection_can_retry");`);
 s=s.replace('                        self->finish();\n                    });\n            });\n    }\n\n    void check',`                        // Reproduce the former policy: without an explicit provider choice,
                        // re-evaluating the non-Bambu slicing profile replaces the fake agent.
                        wxGetApp().printer_agent_override = {};
                        wxGetApp().switch_printer_agent();
                        self->check(wxGetApp().getAgent()->get_printer_agent()->get_agent_info().id !=
                            fake_bambu_printer_agent_id(wxGetApp().app_config), "profile_policy_reproduces_provider_replacement");
                        backend->prepare_connection(name);
                        self->check(backend->connect_printer(name, device, "").empty(), "explicit_connection_restores_provider");
                        wxGetApp().switch_printer_agent();
                        self->check(wxGetApp().getAgent()->get_printer_agent()->get_agent_info().id ==
                            fake_bambu_printer_agent_id(wxGetApp().app_config), "explicit_provider_survives_profile_reevaluation");
                        self->wait_until([backend, name] { return backend->connection(name).state == "verified"; },
                            "connection_receives_fresh_data_after_profile_reevaluation", [self] { self->finish(); });
                    });
            });
    }

    void check`);
 return s;
});
